#include <math.h>
#include <float.h>
#include <string.h>

#define MAXN 16

#define A(i,j) a[(i)*n+(j)]
#define SIGN(a,b) ((b)>=0.0 ? fabs(a) : -fabs(a))

/* Householder reduction to upper Hessenberg form (similarity transform). */
static void hessenberg(double *a, int n)
{
    double v[MAXN];
    for (int k = 0; k < n - 2; k++) {
        int m = n - k - 1;
        double nrm = 0.0;
        for (int i = 0; i < m; i++) {
            double t = A(k + 1 + i, k);
            nrm += t * t;
        }
        nrm = sqrt(nrm);
        if (nrm == 0.0) continue;
        double x0 = A(k + 1, k);
        double alpha = (x0 >= 0.0) ? -nrm : nrm;
        double vv = 0.0;
        for (int i = 0; i < m; i++) {
            v[i] = A(k + 1 + i, k);
        }
        v[0] -= alpha;
        for (int i = 0; i < m; i++) vv += v[i] * v[i];
        if (vv == 0.0) continue;
        double f = 2.0 / vv;

        /* left: A <- H A  (rows k+1..n-1, cols k..n-1) */
        for (int j = k; j < n; j++) {
            double w = 0.0;
            for (int i = 0; i < m; i++) w += v[i] * A(k + 1 + i, j);
            w *= f;
            for (int i = 0; i < m; i++) A(k + 1 + i, j) -= w * v[i];
        }
        /* right: A <- A H  (rows 0..n-1, cols k+1..n-1) */
        for (int i = 0; i < n; i++) {
            double w = 0.0;
            for (int j = 0; j < m; j++) w += A(i, k + 1 + j) * v[j];
            w *= f;
            for (int j = 0; j < m; j++) A(i, k + 1 + j) -= w * v[j];
        }
        A(k + 1, k) = alpha;
        for (int i = 1; i < m; i++) A(k + 1 + i, k) = 0.0;
    }
}

/* Francis double-shift QR on an upper Hessenberg matrix (Numerical Recipes
   hqr, translated to double / 0-based / row-major).  Fills wr, wi.
   Returns 0 on success, -1 if the iteration limit is exceeded. */
static int hqr(double *a, int n, double *wr, double *wi)
{
    int nn, m, l, k, j, its, i, mmin;
    double z, y, x, w, v, u, t, s, r, q, p, anorm;

    anorm = fabs(A(0, 0));
    for (i = 1; i < n; i++)
        for (j = i - 1; j < n; j++)
            anorm += fabs(A(i, j));

    nn = n - 1;
    t = 0.0;
    while (nn >= 0) {
        its = 0;
        do {
            for (l = nn; l >= 1; l--) {
                s = fabs(A(l - 1, l - 1)) + fabs(A(l, l));
                if (s == 0.0) s = anorm;
                if (fabs(A(l, l - 1)) <= DBL_EPSILON * s) {
                    A(l, l - 1) = 0.0;
                    break;
                }
            }
            x = A(nn, nn);
            if (l == nn) {
                wr[nn] = x + t;
                wi[nn] = 0.0;
                nn--;
            } else {
                y = A(nn - 1, nn - 1);
                w = A(nn, nn - 1) * A(nn - 1, nn);
                if (l == nn - 1) {
                    p = 0.5 * (y - x);
                    q = p * p + w;
                    z = sqrt(fabs(q));
                    x += t;
                    if (q >= 0.0) {
                        z = p + SIGN(z, p);
                        wr[nn - 1] = wr[nn] = x + z;
                        if (z != 0.0) wr[nn] = x - w / z;
                        wi[nn - 1] = wi[nn] = 0.0;
                    } else {
                        wr[nn - 1] = wr[nn] = x + p;
                        wi[nn - 1] = -(wi[nn] = z);
                    }
                    nn -= 2;
                } else {
                    if (its == 60) return -1;
                    if (its == 10 || its == 20) {
                        t += x;
                        for (i = 0; i <= nn; i++) A(i, i) -= x;
                        s = fabs(A(nn, nn - 1)) + fabs(A(nn - 1, nn - 2));
                        y = x = 0.75 * s;
                        w = -0.4375 * s * s;
                    }
                    ++its;
                    for (m = nn - 2; m >= l; m--) {
                        z = A(m, m);
                        r = x - z;
                        s = y - z;
                        p = (r * s - w) / A(m + 1, m) + A(m, m + 1);
                        q = A(m + 1, m + 1) - z - r - s;
                        r = A(m + 2, m + 1);
                        s = fabs(p) + fabs(q) + fabs(r);
                        p /= s;
                        q /= s;
                        r /= s;
                        if (m == l) break;
                        u = fabs(A(m, m - 1)) * (fabs(q) + fabs(r));
                        v = fabs(p) * (fabs(A(m - 1, m - 1)) + fabs(z) + fabs(A(m + 1, m + 1)));
                        if (u <= DBL_EPSILON * v) break;
                    }
                    for (i = m + 2; i <= nn; i++) {
                        A(i, i - 2) = 0.0;
                        if (i != m + 2) A(i, i - 3) = 0.0;
                    }
                    for (k = m; k <= nn - 1; k++) {
                        if (k != m) {
                            p = A(k, k - 1);
                            q = A(k + 1, k - 1);
                            r = 0.0;
                            if (k != nn - 1) r = A(k + 2, k - 1);
                            if ((x = fabs(p) + fabs(q) + fabs(r)) != 0.0) {
                                p /= x;
                                q /= x;
                                r /= x;
                            }
                        }
                        if ((s = SIGN(sqrt(p * p + q * q + r * r), p)) != 0.0) {
                            if (k == m) {
                                if (l != m) A(k, k - 1) = -A(k, k - 1);
                            } else {
                                A(k, k - 1) = -s * x;
                            }
                            p += s;
                            x = p / s;
                            y = q / s;
                            z = r / s;
                            q /= p;
                            r /= p;
                            for (j = k; j <= nn; j++) {
                                p = A(k, j) + q * A(k + 1, j);
                                if (k != nn - 1) {
                                    p += r * A(k + 2, j);
                                    A(k + 2, j) -= p * z;
                                }
                                A(k + 1, j) -= p * y;
                                A(k, j) -= p * x;
                            }
                            mmin = (nn < k + 3) ? nn : k + 3;
                            for (i = l; i <= mmin; i++) {
                                p = x * A(i, k) + y * A(i, k + 1);
                                if (k != nn - 1) {
                                    p += z * A(i, k + 2);
                                    A(i, k + 2) -= p * r;
                                }
                                A(i, k + 1) -= p * q;
                                A(i, k) -= p;
                            }
                        }
                    }
                }
            }
        } while (l < nn - 1);
    }
    return 0;
}

/* Complex LU factorization with partial pivoting, row-major n x n. */
static void clu_factor(double *ar, double *ai, int n, int *piv)
{
    for (int k = 0; k < n; k++) {
        int p = k;
        double best = ar[k * n + k] * ar[k * n + k] + ai[k * n + k] * ai[k * n + k];
        for (int i = k + 1; i < n; i++) {
            double val = ar[i * n + k] * ar[i * n + k] + ai[i * n + k] * ai[i * n + k];
            if (val > best) { best = val; p = i; }
        }
        piv[k] = p;
        if (p != k) {
            for (int j = k; j < n; j++) {
                double tr = ar[k * n + j], ti = ai[k * n + j];
                ar[k * n + j] = ar[p * n + j]; ai[k * n + j] = ai[p * n + j];
                ar[p * n + j] = tr; ai[p * n + j] = ti;
            }
        }
        double dr = ar[k * n + k], di = ai[k * n + k];
        double den = dr * dr + di * di;
        if (den == 0.0) {
            /* exactly singular pivot: nudge */
            dr = DBL_EPSILON; di = 0.0;
            ar[k * n + k] = dr; ai[k * n + k] = 0.0;
            den = dr * dr;
        }
        for (int i = k + 1; i < n; i++) {
            double xr = ar[i * n + k], xi = ai[i * n + k];
            double mr = (xr * dr + xi * di) / den;
            double mi = (xi * dr - xr * di) / den;
            ar[i * n + k] = mr; ai[i * n + k] = mi;
            for (int j = k + 1; j < n; j++) {
                ar[i * n + j] -= mr * ar[k * n + j] - mi * ai[k * n + j];
                ai[i * n + j] -= mr * ai[k * n + j] + mi * ar[k * n + j];
            }
        }
    }
}

static void clu_solve(const double *ar, const double *ai, int n, const int *piv,
                      double *br, double *bi)
{
    for (int k = 0; k < n; k++) {
        int p = piv[k];
        if (p != k) {
            double tr = br[k], ti = bi[k];
            br[k] = br[p]; bi[k] = bi[p];
            br[p] = tr; bi[p] = ti;
        }
    }
    for (int i = 0; i < n; i++) {
        double sr = br[i], si = bi[i];
        for (int j = 0; j < i; j++) {
            sr -= ar[i * n + j] * br[j] - ai[i * n + j] * bi[j];
            si -= ar[i * n + j] * bi[j] + ai[i * n + j] * br[j];
        }
        br[i] = sr; bi[i] = si;
    }
    for (int i = n - 1; i >= 0; i--) {
        double sr = br[i], si = bi[i];
        for (int j = i + 1; j < n; j++) {
            sr -= ar[i * n + j] * br[j] - ai[i * n + j] * bi[j];
            si -= ar[i * n + j] * bi[j] + ai[i * n + j] * br[j];
        }
        double dr = ar[i * n + i], di = ai[i * n + i];
        double den = dr * dr + di * di;
        br[i] = (sr * dr + si * di) / den;
        bi[i] = (si * dr - sr * di) / den;
    }
}

/* Solve (A - lambda I) x = b repeatedly from a fixed starting vector and
   return the normalized vector in vr/vi. */
static void inverse_iteration(const double *a, int n, double lr, double li,
                              double *vr, double *vi)
{
    double ar[MAXN * MAXN], ai[MAXN * MAXN];
    int piv[MAXN];
    double br[MAXN], bi[MAXN];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            ar[i * n + j] = a[i * n + j];
            ai[i * n + j] = 0.0;
        }
        ar[i * n + i] -= lr;
        ai[i * n + i] -= li;
    }
    clu_factor(ar, ai, n, piv);

    unsigned int seed = 12345u;
    for (int i = 0; i < n; i++) {
        seed = seed * 1103515245u + 12345u;
        br[i] = (double)((seed >> 16) & 0x7fff) / 32768.0 - 0.5;
        bi[i] = 0.0;
    }

    for (int it = 0; it < 3; it++) {
        clu_solve(ar, ai, n, piv, br, bi);
        double nrm = 0.0;
        for (int i = 0; i < n; i++) nrm += br[i] * br[i] + bi[i] * bi[i];
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm)) {
            /* restart with a different vector */
            seed = 987654321u + it;
            for (int i = 0; i < n; i++) {
                seed = seed * 1103515245u + 12345u;
                br[i] = (double)((seed >> 16) & 0x7fff) / 32768.0 - 0.5;
                bi[i] = 0.0;
            }
            continue;
        }
        for (int i = 0; i < n; i++) { br[i] /= nrm; bi[i] /= nrm; }
    }
    for (int i = 0; i < n; i++) { vr[i] = br[i]; vi[i] = bi[i]; }
}

/* Return 0 and fill eigenvalue + eigenvector on success; nonzero on failure. */
int dominant_eig(const double *ain, int n, double *out)
{
    double a[MAXN * MAXN];
    double wr[MAXN], wi[MAXN], vr[MAXN], vi[MAXN];

    if (n <= 0 || n > MAXN) return 1;
    for (int i = 0; i < n * n; i++) a[i] = ain[i];

    if (n == 1) {
        out[0] = a[0];
        out[1] = 0.0;
        out[2] = 1.0;
        out[3] = 0.0;
        return 0;
    }

    hessenberg(a, n);
    if (hqr(a, n, wr, wi) != 0) return 2;

    int idx = 0;
    double best = -1.0;
    for (int i = 0; i < n; i++) {
        double mag = wr[i] * wr[i] + wi[i] * wi[i];
        if (!isfinite(mag)) return 3;
        if (mag > best) { best = mag; idx = i; }
    }
    double lr = wr[idx], li = wi[idx];

    inverse_iteration(ain, n, lr, li, vr, vi);

    double nrm = 0.0;
    for (int i = 0; i < n; i++) nrm += vr[i] * vr[i] + vi[i] * vi[i];
    if (!(nrm > 0.0) || !isfinite(nrm)) return 4;

    /* residual check: |A v - lambda v| <= atol + rtol * |lambda v| */
    const double atol = 5e-9, rtol = 5e-6;
    int ok = 1;
    for (int i = 0; i < n; i++) {
        double rr = 0.0, ri = 0.0;
        for (int j = 0; j < n; j++) {
            double av_r = ain[i * n + j] * vr[j];
            double av_i = ain[i * n + j] * vi[j];
            rr += av_r;
            ri += av_i;
        }
        /* lambda * v */
        double lvr = lr * vr[i] - li * vi[i];
        double lvi = lr * vi[i] + li * vr[i];
        double dr = rr - lvr, di = ri - lvi;
        double err = sqrt(dr * dr + di * di);
        double scale = atol + rtol * sqrt(lvr * lvr + lvi * lvi);
        if (!isfinite(err) || err > scale) { ok = 0; break; }
    }
    if (!ok) return 5;

    out[0] = lr;
    out[1] = li;
    for (int i = 0; i < n; i++) {
        out[2 + 2 * i] = vr[i];
        out[3 + 2 * i] = vi[i];
    }
    return 0;
}
